import { useState } from 'react';
import Section from '../../components/Section/Section';
import Button  from '../../components/Button/Button';
import { SITE_CONFIG, getWhatsAppUrl, getPhoneUrl } from '../../config/site';
import styles from './Contact.module.css';

export default function Contact() {
  const [form, setForm] = useState({ name: '', service: '', message: '' });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    setForm((f) => ({ ...f, [e.target.name]: e.target.value }));
  };

  // Build a pre-filled WhatsApp message from the form data
  const handleWhatsAppSubmit = (e) => {
    e.preventDefault();
    const msg =
      `Bonjour, je m'appelle ${form.name}.\n` +
      `Service souhaité : ${form.service || 'Non précisé'}\n` +
      `Message : ${form.message}`;
    window.open(getWhatsAppUrl(msg), '_blank', 'noopener,noreferrer');
    setSubmitted(true);
  };

  return (
    <>
      {/* Page header */}
      <div className={styles.pageHeader}>
        <div className="container">
          <h1 className={styles.pageTitle}>Nous contacter</h1>
          <p className={styles.pageSub}>
            Répondons à votre demande sous 2h en jours ouvrés
          </p>
        </div>
      </div>

      <Section variant="light">
        <div className={styles.grid}>

          {/* ── Left: direct contact ─────────────────────── */}
          <div className={styles.directContact}>
            <h2 className={styles.colTitle}>Joignez-nous directement</h2>
            <p className={styles.colSub}>
              Le moyen le plus rapide est WhatsApp — réponse garantie sous 2h.
            </p>

            <div className={styles.ctaBtns}>
              <Button variant="whatsapp" full size="lg" href={getWhatsAppUrl()}>
                💬 Écrire sur WhatsApp
              </Button>
              <Button variant="navy" full size="lg" href={getPhoneUrl()}>
                📞 Appeler maintenant
              </Button>
            </div>

            {/* Info rows */}
            <div className={styles.infoList}>
              <div className={styles.infoRow}>
                <span className={styles.infoIcon}>📍</span>
                <div>
                  <p className={styles.infoLabel}>Adresse</p>
                  <p className={styles.infoValue}>{SITE_CONFIG.address}</p>
                </div>
              </div>
              <div className={styles.infoRow}>
                <span className={styles.infoIcon}>🕘</span>
                <div>
                  <p className={styles.infoLabel}>Horaires</p>
                  <p className={styles.infoValue}>{SITE_CONFIG.hours}</p>
                </div>
              </div>
              <div className={styles.infoRow}>
                <span className={styles.infoIcon}>✉️</span>
                <div>
                  <p className={styles.infoLabel}>Email</p>
                  <p className={styles.infoValue}>{SITE_CONFIG.email}</p>
                </div>
              </div>
              <div className={styles.infoRow}>
                <span className={styles.infoIcon}>👤</span>
                <div>
                  <p className={styles.infoLabel}>Facilitateur</p>
                  <p className={styles.infoValue}>{SITE_CONFIG.facilitator}</p>
                </div>
              </div>
            </div>

            {/* WhatsApp tip */}
            <div className={styles.tip}>
              <p className={styles.tipLabel}>💡 Message suggéré pour WhatsApp :</p>
              <p className={styles.tipText}>
                « Bonjour, je souhaite obtenir [nom du service]. Pouvez-vous me
                donner les informations nécessaires ? »
              </p>
            </div>
          </div>

          {/* ── Right: contact form ───────────────────────── */}
          <div className={styles.formWrap}>
            <h2 className={styles.colTitle}>Formulaire de contact</h2>
            <p className={styles.colSub}>
              Remplissez le formulaire — il sera envoyé via WhatsApp.
            </p>

            {submitted ? (
              <div className={styles.success}>
                <span className={styles.successIcon}>✅</span>
                <h3>Message envoyé !</h3>
                <p>Votre demande a été ouverte dans WhatsApp. Nous vous répondrons sous 2h.</p>
                <Button variant="primary" onClick={() => setSubmitted(false)}>
                  Nouvelle demande
                </Button>
              </div>
            ) : (
              <form onSubmit={handleWhatsAppSubmit} className={styles.form}>
                <div className={styles.formGroup}>
                  <label className={styles.label} htmlFor="name">Votre prénom *</label>
                  <input
                    id="name"
                    name="name"
                    type="text"
                    required
                    placeholder="Ex : Marie"
                    value={form.name}
                    onChange={handleChange}
                    className={styles.input}
                  />
                </div>

                <div className={styles.formGroup}>
                  <label className={styles.label} htmlFor="service">Service souhaité</label>
                  <select
                    id="service"
                    name="service"
                    value={form.service}
                    onChange={handleChange}
                    className={styles.input}
                  >
                    <option value="">Choisir un service…</option>
                    {SITE_CONFIG.services.map((s) => (
                      <option key={s.id} value={s.title}>{s.title}</option>
                    ))}
                    <option value="Transport Paris → Bruxelles">Transport Paris → Bruxelles</option>
                    <option value="Autre / Conseil gratuit">Autre / Conseil gratuit</option>
                  </select>
                </div>

                <div className={styles.formGroup}>
                  <label className={styles.label} htmlFor="message">Votre message *</label>
                  <textarea
                    id="message"
                    name="message"
                    required
                    rows={4}
                    placeholder="Décrivez votre situation en quelques mots…"
                    value={form.message}
                    onChange={handleChange}
                    className={styles.input}
                  />
                </div>

                <Button variant="whatsapp" full type="submit">
                  💬 Envoyer via WhatsApp →
                </Button>

                <p className={styles.formNote}>
                  * Le formulaire ouvrira WhatsApp avec votre message pré-rempli.
                </p>
              </form>
            )}
          </div>
        </div>
      </Section>
    </>
  );
}
